from pathlib import Path
svg='<svg xmlns="http://www.w3.org/2000/svg" width="680" height="160" viewBox="0 0 680 160" role="img">\n<title>Skyline STL</title><desc>stencil for 3D print</desc>\n<style>@media (prefers-reduced-motion: reduce){*{animation:none!important;transition:none!important}} @keyframes lift{from{transform:translateY(20px)}to{transform:translateY(0)}} .bar{animation:lift .5s forwards;transform:translateY(20px)}</style>\n<rect width="680" height="160" rx="16" fill="#f8fafc"/>\n<text x="20" y="28" fill="#1c1917" font-family="monospace" font-size="12">GH-SKYLINE — STL for 3D printer</text>\n<g transform="translate(20,44)">\n  <rect width="640" height="80" rx="6" fill="#e7e5e4" stroke="#a8a29e"/>\n  <rect class="bar" x="0" y="32" width="8" height="28" fill="#1c1917" style="animation-delay:.02s"/>\n  <rect class="bar" x="11" y="28" width="8" height="32" fill="#1c1917" style="animation-delay:.04s"/>\n  <rect class="bar" x="22" y="24" width="8" height="36" fill="#1c1917" style="animation-delay:.06s"/>\n  <rect class="bar" x="33" y="36" width="8" height="24" fill="#1c1917" style="animation-delay:.08s"/>\n  <rect class="bar" x="44" y="20" width="8" height="40" fill="#1c1917" style="animation-delay:.10s"/>\n  <rect class="bar" x="55" y="30" width="8" height="30" fill="#1c1917" style="animation-delay:.12s"/>\n  <text x="320" y="96" text-anchor="middle" fill="#57534e" font-family="monospace" font-size="8">gh skyline --year 2024 --output skyline.stl</text>\n</g>\n</svg>\n'
Path(__file__).resolve().parents[2].joinpath('assets','skyline-stl.svg').write_text(svg, encoding='utf-8')
print('Wrote assets/skyline-stl.svg')
